        if (!(lfs->lookahead.buffer[lfs->lookahead.next / 8] & (1U << (lfs->lookahead.next % 8)))) {
            block = lfs->lookahead.start + lfs->lookahead.next;
            lfs->lookahead.buffer[lfs->lookahead.next / 8] |= (1U << (lfs->lookahead.next % 8));
            break;
        }
        lfs->lookahead.next++;
    }

    // If no free block found in lookahead, scan the entire block space
    if (block == LFS_BLOCK_NULL) {
        // Reset lookahead
        lfs->lookahead.start = 0;
        lfs->lookahead.size = lfs_min(lfs->cfg->lookahead_size * 8, lfs->block_count);
        lfs->lookahead.next = 0;

        // Scan blocks for a free one
        for (lfs_block_t i = 0; i < lfs->block_count; i++) {
            // Check if block is free (not in lookahead buffer)
            if (!(lfs->lookahead.buffer[i / 8] & (1U << (i % 8)))) {
                // Check wear leveling (if enabled)
                if (lfs->cfg->block_cycles != (uint32_t)-1) {
                    // Read block metadata to check erase count
                    lfs_emubd_wear_t wear;
                    int err = lfs->cfg->read(lfs->cfg, i, 0, &wear, sizeof(wear));
                    if (err) {
                        return err;
                    }

                    // Skip blocks with high erase counts
                    if (wear >= lfs->cfg->block_cycles) {
                        continue;
                    }
                }

                // Found a free block
                block = i;
                lfs->lookahead.buffer[i / 8] |= (1U << (i % 8));
                lfs->lookahead.next = i + 1;
                break;
            }
        }
    }

    // If no free block found, return error
    if (block == LFS_BLOCK_NULL) {
        return LFS_ERR_NOSPC;
    }

    // Update lookahead window
    if (lfs->lookahead.next >= lfs->lookahead.size) {
        lfs->lookahead.start += lfs->lookahead.size;
        lfs->lookahead.size = lfs_min(lfs->cfg->lookahead_size * 8, lfs->block_count - lfs->lookahead.start);
        lfs->lookahead.next = 0;
    }

    *block = block;
    return 0;
